"""Tensor-parallel linear layers (Megatron-style).

Weight layout follows torch.nn.Linear: weight has shape (out_features, in_features)
and y = x @ W^T + b.

ColumnParallelLinear: the output dimension (columns of W^T) is split across ranks.
    Each rank computes y_i = x @ W_i^T + b_i, then outputs are all-gathered and
    concatenated along the last dimension.

RowParallelLinear: the input dimension (rows of W^T) is split across ranks.
    Each rank computes partial y_i = x_i @ W_i^T, partials are all-reduced (summed)
    and the full bias is added.
"""

import torch
import torch.distributed as dist


def _world_size():
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size()
    return 1


def _rank():
    if dist.is_available() and dist.is_initialized():
        return dist.get_rank()
    return 0


def _divide(numerator, denominator):
    assert numerator % denominator == 0, (
        f"{numerator} is not divisible by {denominator}"
    )
    return numerator // denominator


# --------------------------------------------------------------------------- #
# Communication primitives with autograd support
# --------------------------------------------------------------------------- #
def _all_reduce(x):
    if _world_size() == 1:
        return x
    x = x.contiguous().clone()
    dist.all_reduce(x, op=dist.ReduceOp.SUM)
    return x


def _split_last_dim(x):
    ws = _world_size()
    if ws == 1:
        return x
    chunk = _divide(x.size(-1), ws)
    r = _rank()
    return x[..., r * chunk:(r + 1) * chunk].contiguous()


def _gather_last_dim(x):
    ws = _world_size()
    if ws == 1:
        return x
    x = x.contiguous()
    tensors = [torch.empty_like(x) for _ in range(ws)]
    dist.all_gather(tensors, x)
    return torch.cat(tensors, dim=-1).contiguous()


class _CopyToParallelRegion(torch.autograd.Function):
    """Identity in forward, all-reduce of gradient in backward."""

    @staticmethod
    def forward(ctx, x):
        return x

    @staticmethod
    def backward(ctx, grad_output):
        return _all_reduce(grad_output)


class _ReduceFromParallelRegion(torch.autograd.Function):
    """All-reduce in forward, identity in backward."""

    @staticmethod
    def forward(ctx, x):
        return _all_reduce(x)

    @staticmethod
    def backward(ctx, grad_output):
        return grad_output


class _ScatterToParallelRegion(torch.autograd.Function):
    """Split along last dim in forward, all-gather in backward."""

    @staticmethod
    def forward(ctx, x):
        return _split_last_dim(x)

    @staticmethod
    def backward(ctx, grad_output):
        return _gather_last_dim(grad_output)


class _GatherFromParallelRegion(torch.autograd.Function):
    """All-gather along last dim in forward, split in backward."""

    @staticmethod
    def forward(ctx, x):
        return _gather_last_dim(x)

    @staticmethod
    def backward(ctx, grad_output):
        return _split_last_dim(grad_output)


def copy_to_parallel_region(x):
    return _CopyToParallelRegion.apply(x)


def reduce_from_parallel_region(x):
    return _ReduceFromParallelRegion.apply(x)


def scatter_to_parallel_region(x):
    return _ScatterToParallelRegion.apply(x)


def gather_from_parallel_region(x):
    return _GatherFromParallelRegion.apply(x)


# --------------------------------------------------------------------------- #
# Layers
# --------------------------------------------------------------------------- #
class ColumnParallelLinear(torch.nn.Module):
    """Linear layer whose weight is split along the output dimension."""

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _world_size()
        self.rank = _rank()
        self.output_size_per_partition = _divide(out_features, self.world_size)

        assert master_weight is not None, "master_weight must be provided"
        master_weight = master_weight.detach()
        assert tuple(master_weight.shape) == (out_features, in_features), (
            f"master_weight shape {tuple(master_weight.shape)} != "
            f"{(out_features, in_features)}"
        )

        start = self.rank * self.output_size_per_partition
        end = start + self.output_size_per_partition
        self.weight = torch.nn.Parameter(master_weight[start:end, :].clone().contiguous())

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(
                    self.output_size_per_partition,
                    dtype=master_weight.dtype,
                    device=master_weight.device,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        x_parallel = copy_to_parallel_region(x)
        out_parallel = torch.nn.functional.linear(x_parallel, self.weight, self.bias)
        return gather_from_parallel_region(out_parallel)


class RowParallelLinear(torch.nn.Module):
    """Linear layer whose weight is split along the input dimension."""

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _world_size()
        self.rank = _rank()
        self.input_size_per_partition = _divide(in_features, self.world_size)

        assert master_weight is not None, "master_weight must be provided"
        master_weight = master_weight.detach()
        assert tuple(master_weight.shape) == (out_features, in_features), (
            f"master_weight shape {tuple(master_weight.shape)} != "
            f"{(out_features, in_features)}"
        )

        start = self.rank * self.input_size_per_partition
        end = start + self.input_size_per_partition
        self.weight = torch.nn.Parameter(master_weight[:, start:end].clone().contiguous())

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(
                    out_features,
                    dtype=master_weight.dtype,
                    device=master_weight.device,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        # Accept either the full input (split here) or an already-partitioned input.
        if x.size(-1) == self.input_size_per_partition and self.world_size > 1:
            x_parallel = x
        else:
            assert x.size(-1) == self.in_features, (
                f"input last dim {x.size(-1)} matches neither in_features "
                f"({self.in_features}) nor partition size "
                f"({self.input_size_per_partition})"
            )
            x_parallel = scatter_to_parallel_region(x)
        partial = torch.nn.functional.linear(x_parallel, self.weight)
        out = reduce_from_parallel_region(partial)
        if self.bias is not None:
            out = out + self.bias
        return out
